<script setup lang="ts">
import { computed,ref } from 'vue';
import { compareReleaseNewest,releaseMetadata } from '../domain/catalog-release';
import GameIcon from './GameIcon.vue';
import LibraryToolbar from './LibraryToolbar.vue';
import CharacterLibraryTools from './CharacterLibraryTools.vue';
import SortPanel from './SortPanel.vue';
import RarityFilter from './RarityFilter.vue';
import FilterActions from './FilterActions.vue';
import FilterPanel from './FilterPanel.vue';
import WorkbenchDialog from './WorkbenchDialog.vue';
const props=defineProps<{options:{id:string;name:string;element?:string;rarity?:number;weaponType?:string}[];kind:'characters'|'weapons'|'artifacts';label:string;selectedId?:string;imageSize?:number;itemLabelPrefix?:string}>();
const emit=defineEmits<{select:[id:string]}>();
const query=ref(''),sort=ref('release'),direction=ref<'asc'|'desc'>('desc'),rarity=ref<string[]>([]),sortOpen=ref(false),filterOpen=ref(false);
const characterElements=ref<string[]>([]),characterWeapons=ref<string[]>([]),characterRarities=ref<string[]>([]);
function entryRarity(entry:typeof props.options[number]){return entry.rarity ?? releaseMetadata(props.kind,entry.id,entry.name)?.rarity;}
const rarities=computed(()=>[...new Set(props.options.map(entryRarity).filter((value):value is number=>value!==undefined))].sort((a,b)=>b-a));
const entries=computed(()=>props.options.filter(entry=>entry.name.includes(query.value.trim()) && (props.kind==='characters'?(!characterElements.value.length || characterElements.value.includes(entry.element ?? '')) && (!characterWeapons.value.length || characterWeapons.value.includes(entry.weaponType ?? '')) && (!characterRarities.value.length || characterRarities.value.includes(String(entryRarity(entry)))):!rarity.value.length || rarity.value.includes(String(entryRarity(entry))))).sort((a,b)=>(direction.value==='desc'?1:-1)*(sort.value==='release'?compareReleaseNewest(releaseMetadata(props.kind,a.id,a.name),releaseMetadata(props.kind,b.id,b.name)):b.name.localeCompare(a.name,'zh-CN')) || a.name.localeCompare(b.name,'zh-CN')));
</script>
<template><section class="catalog-browser" :class="{'character-catalog':kind==='characters'}"><CharacterLibraryTools v-if="kind==='characters'" v-model:query="query" v-model:elements="characterElements" v-model:weapons="characterWeapons" v-model:rarities="characterRarities" v-model:sort="sort" v-model:direction="direction" :label="`搜索${label}`" :sort-options="[{value:'release',label:'实装版本'},{value:'name',label:'名称'}]" /><LibraryToolbar v-else v-model="query" :label="`搜索${label}`" placeholder="查找名称…" :filter-count="rarity.length" :sorted="sort!=='release' || direction!=='desc'" @sort="sortOpen=true" @filter="filterOpen=true" @reset="rarity=[];sort='release';direction='desc'" /><div class="catalog-browser-options"><button v-for="entry in entries" :key="entry.id" class="catalog-browser-item" :data-rarity="entryRarity(entry)" :style="{'--catalog-image-size':(imageSize ?? 64)+'px','--catalog-rarity-border':`var(--rarity-${entryRarity(entry)}-border,var(--line))`}" :class="{selected:entry.id===selectedId}" :aria-label="`${itemLabelPrefix ?? '选择'}${entry.name}`" @click="emit('select',entry.id)"><GameIcon :kind="kind" :id="entry.id" :name="entry.name" :size="imageSize ?? 64" :rarity="entryRarity(entry)" /><strong :title="entry.name">{{ entry.name }}</strong></button></div><p v-if="!entries.length">没有符合条件的内容。</p><WorkbenchDialog v-if="sortOpen" center-title title="目录排序" size="filter" @close="sortOpen=false"><SortPanel v-model="sort" v-model:direction="direction" :options="[{value:'release',label:'实装版本'},{value:'name',label:'名称'}]" @reset="sort='release';direction='desc'" @confirm="sortOpen=false" /></WorkbenchDialog><WorkbenchDialog v-if="filterOpen" center-title title="筛选目录" size="filter" @close="filterOpen=false"><FilterPanel><section v-if="rarities.length" aria-label="星级"><h3>星级</h3><RarityFilter v-model="rarity" :rarities="rarities" /></section></FilterPanel><template #footer><FilterActions flush @reset="rarity=[]" @confirm="filterOpen=false" /></template></WorkbenchDialog></section></template>
<style scoped>.catalog-browser { display:grid; gap:16px; min-width:0; }.character-catalog { display:block; }.character-catalog .catalog-browser-options { margin-top:16px; }.catalog-browser-options { display:grid; grid-template-columns:repeat(auto-fill,minmax(116px,1fr)); gap:12px; }.catalog-browser-item { display:grid; grid-template-rows:var(--catalog-image-size) 44px; align-items:center; justify-items:center; align-content:start; gap:10px; padding:12px; border:1px solid var(--line); border-top:3px solid var(--catalog-rarity-border); border-radius:10px; background:var(--surface); color:var(--ink); font-size:var(--font-control); }.catalog-browser-item:hover,.catalog-browser-item.selected { border-top-color:var(--element-anemo-primary); }.catalog-browser-item.selected { background:var(--element-anemo-light); }.catalog-browser-item strong { display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical; overflow:hidden; max-width:100%; line-height:22px; }.catalog-browser p { font-size:var(--font-control); }</style>
